<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pageTitle='Expenses';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$category=trim((string)($_POST['category']??''));$desc=trim((string)($_POST['description']??''));$amount=(float)($_POST['amount']??0);$date=$_POST['expense_date']??date('Y-m-d');if($category===''||$desc===''||$amount<=0)throw new RuntimeException('Enter a category, description, and amount greater than zero.');$stmt=$pdo->prepare('INSERT INTO expenses(category,description,amount,expense_date,created_by) VALUES(?,?,?,?,?)');$stmt->execute([$category,$desc,$amount,$date,$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();log_action($pdo,'create','expense',$id,$desc);flash('success','Expense recorded.');}catch(Throwable $ex){flash('error',$ex instanceof PDOException?'Could not save expense.':$ex->getMessage());}header('Location: expenses.php');exit;}
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$stmt=$pdo->prepare('SELECT e.*,u.name creator FROM expenses e JOIN users u ON u.id=e.created_by WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date DESC,e.id DESC');$stmt->execute([$from,$to]);$rows=$stmt->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['amount'],$rows));require __DIR__.'/includes/header.php';
?>
<div class="stats-grid compact-stats"><article class="stat-card"><span class="muted">Expenses in selected period</span><strong><?= money($total) ?></strong></article><article class="stat-card"><span class="muted">Expense entries</span><strong><?= count($rows) ?></strong></article></div><div class="dashboard-grid"><div class="panel"><div class="panel-heading"><div><h3>Add expense</h3><p>Record day-to-day operating costs.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="field"><label>Category *</label><select name="category" required><?php foreach(['Utilities','Transportation','Packaging','Store supplies','Maintenance','Rent','Other'] as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></div><div class="field"><label>Amount (₱) *</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div class="field"><label>Description *</label><input name="description" required maxlength="255" placeholder="e.g. Electricity bill"></div><div class="field"><label>Expense date *</label><input type="date" name="expense_date" value="<?= date('Y-m-d') ?>" required></div><div class="field field-action"><button class="btn primary">Save expense</button></div></form></div><div class="panel"><div class="panel-heading"><div><h3>Expense tracking</h3><p>Keep your operating costs visible.</p></div></div><div class="info-card"><span class="stat-icon orange">₱</span><strong>Record every expense</strong><p>Include utilities, transportation, packaging, and other store costs to make profit estimates more meaningful.</p></div><div class="info-card"><span class="stat-icon green">↗</span><strong>Filter by date</strong><p>Use the date range to review costs for a particular day, week, or month.</p></div></div></div><div class="panel"><div class="panel-heading"><div><h3>Expense history</h3><p><?= count($rows) ?> records in the selected date range.</p></div></div><form method="get" class="filter-bar"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn secondary">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Recorded by</th><th class="align-right">Amount</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= date('M j, Y',strtotime($r['expense_date'])) ?></td><td><span class="badge muted-badge"><?= e($r['category']) ?></span></td><td><?= e($r['description']) ?></td><td><?= e($r['creator']) ?></td><td class="align-right"><?= money($r['amount']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state compact"><strong>No expenses in this period</strong></div></td></tr><?php endif; ?></tbody><tfoot><tr><th colspan="4">Period total</th><th class="align-right"><?= money($total) ?></th></tr></tfoot></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
